tools.example:
// ExtendScript: save the current selection to a new alpha channel
var doc = app.activeDocument;
var alpha = doc.channels.add();
alpha.name = "Sky mask";
alpha.kind = ChannelType.MASKEDAREA;

// ExtendScript: turn the first saved path into a selection and fill it
var doc = app.activeDocument;
doc.pathItems[0].makeSelection(0, true, SelectionType.REPLACE);
doc.selection.fill(app.foregroundColor);
doc.selection.deselect();

// ExtendScript: play an action from a named set
app.doAction("Vignette (selection)", "Default Actions");

// Step list for recording one:
// 1. Alt+F9 to open the Actions panel.
// 2. Click the folder icon to create a set, then the plus icon to create an action and click Record.
// 3. Perform the edits; click the square Stop icon when finished.
// 4. Panel menu > Save Actions... to write the set to an .atn file.
// 5. File > Automate > Batch... to run it over a folder.

// ExtendScript: write a PNG through the Save for Web engine
var opts = new ExportOptionsSaveForWeb();
opts.format = SaveDocumentType.PNG;
opts.PNG8 = false;
opts.transparency = true;
app.activeDocument.exportDocument(new File("D:/out/hero.png"), ExportType.SAVEFORWEB, opts);

// Step list for the UI route:
// 1. File > Export > Export Preferences... and set Quick Export to PNG with an assets folder.
// 2. Right-click the layer or artboard in the Layers panel and choose Quick Export as PNG for one-click output.
// 3. For full control use File > Export > Export As... (Alt+Shift+Ctrl+W) and tick Scale All Sizes for 2x and 3x.
// 4. For a precise file-size budget use File > Export > Save for Web (Legacy)... (Alt+Shift+Ctrl+S) and watch the size readout under the preview.

// ExtendScript: print the active document with Photoshop managing colour
app.activeDocument.print(SourceSpaceType.DOCUMENT, "Adobe RGB (1998)", Intent.RELATIVECOLORIMETRIC, true);

// Step list for the UI route:
// 1. View > Proof Setup > Custom... and pick the printer/paper profile, then View > Proof Colors (Ctrl+Y) to soft-proof.
// 2. View > Gamut Warning (Shift+Ctrl+Y) to see which colours cannot be printed, and adjust them.
// 3. File > Print... (Ctrl+P).
// 4. Expand Color Management, set Color Handling to Photoshop Manages Colors, choose the Printer Profile and set Rendering Intent to Relative Colorimetric with Black Point Compensation.
// 5. Click Print Settings... and turn colour management OFF in the printer driver, then print.
